def trap_rain_water(height_map):
    m, n = len(height_map), len(height_map[0])
    if m < 3 or n < 3:
        return 0
    inf = float('inf')
    water = [[inf] * n for _ in range(m)]                                   # water[i][j] = the lowest possible "water surface" level at this cell
    for i in range(m):
        water[i][0] = height_map[i][0]                                     # border cells never trap water; fix their level to their own height
        water[i][n - 1] = height_map[i][n - 1]
    for j in range(n):
        water[0][j] = height_map[0][j]
        water[m - 1][j] = height_map[m - 1][j]

    changed = True
    while changed:                                                          # repeatedly relax every interior cell's level until nothing improves
        changed = False
        for i in range(1, m - 1):
            for j in range(1, n - 1):
                min_neighbor = min(water[i - 1][j], water[i + 1][j], water[i][j - 1], water[i][j + 1])
                new_level = max(height_map[i][j], min_neighbor)
                if new_level < water[i][j]:
                    water[i][j] = new_level
                    changed = True

    total = 0
    for i in range(1, m - 1):
        for j in range(1, n - 1):
            total += water[i][j] - height_map[i][j]
    return total


if __name__ == "__main__":
    height_map = [[1, 4, 3, 1, 3, 2], [3, 2, 1, 3, 2, 4], [2, 3, 3, 2, 3, 1]]
    print(trap_rain_water(height_map))

