import java.util.*;

public class Main {
    // Conceptual brute force: repeatedly relax every interior cell's water level
    // against its 4 neighbors until nothing changes (a fixed-point iteration),
    // analogous to Bellman-Ford relaxing edges repeatedly instead of Dijkstra's
    // one-shot, priority-ordered approach.
    int trapRainWaterBruteForce(int[][] heightMap) {
        int m = heightMap.length, n = heightMap[0].length;
        if (m < 3 || n < 3) return 0;
        int[][] water = new int[m][n];
        for (int[] row : water) Arrays.fill(row, Integer.MAX_VALUE);
        for (int i = 0; i < m; i++) {
            water[i][0] = heightMap[i][0];
            water[i][n - 1] = heightMap[i][n - 1];
        }
        for (int j = 0; j < n; j++) {
            water[0][j] = heightMap[0][j];
            water[m - 1][j] = heightMap[m - 1][j];
        }
        boolean changed = true;
        while (changed) {                                                          // repeatedly relax until no cell's level can be lowered further
            changed = false;
            for (int i = 1; i < m - 1; i++) {
                for (int j = 1; j < n - 1; j++) {
                    int minNeighbor = Math.min(Math.min(water[i - 1][j], water[i + 1][j]), Math.min(water[i][j - 1], water[i][j + 1]));
                    int newLevel = Math.max(heightMap[i][j], minNeighbor);
                    if (newLevel < water[i][j]) {
                        water[i][j] = newLevel;
                        changed = true;
                    }
                }
            }
        }
        int total = 0;
        for (int i = 1; i < m - 1; i++) {
            for (int j = 1; j < n - 1; j++) {
                total += water[i][j] - heightMap[i][j];
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[][] heightMap = {{1, 4, 3, 1, 3, 2}, {3, 2, 1, 3, 2, 4}, {2, 3, 3, 2, 3, 1}};
        System.out.println(solution.trapRainWaterBruteForce(heightMap));
    }
}

