import heapq

def trap_rain_water(height_map):
    m, n = len(height_map), len(height_map[0])
    if m < 3 or n < 3:
        return 0
    visited = [[False] * n for _ in range(m)]
    heap = []                                                               # min-heap of (height, row, col), starting with every border cell
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(heap, (height_map[i][j], i, j))
                visited[i][j] = True
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    water = 0
    while heap:
        height, i, j = heapq.heappop(heap)                                 # always expand from the CURRENT lowest wall
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < m and 0 <= nj < n and not visited[ni][nj]:
                visited[ni][nj] = True
                water += max(0, height - height_map[ni][nj])               # trapped water = wall height minus this cell's own height
                heapq.heappush(heap, (max(height, height_map[ni][nj]), ni, nj))  # push back with the EFFECTIVE (raised) wall height
    return water


if __name__ == "__main__":
    height_map = [[1, 4, 3, 1, 3, 2], [3, 2, 1, 3, 2, 4], [2, 3, 3, 2, 3, 1]]
    print(trap_rain_water(height_map))

