public class Main {
    int trapRainWater(int[][] heightMap) {
        int m = heightMap.length, n = heightMap[0].length;
        if (m < 3 || n < 3) return 0;
        boolean[][] visited = new boolean[m][n];
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[0] - b[0]);     // min-heap of {height, row, col}, starting with every border cell
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 || i == m - 1 || j == 0 || j == n - 1) {
                    heap.offer(new int[]{heightMap[i][j], i, j});
                    visited[i][j] = true;
                }
            }
        }
        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
        int water = 0;
        while (!heap.isEmpty()) {
            int[] cur = heap.poll();                                                 // always expand from the CURRENT lowest wall
            int height = cur[0], i = cur[1], j = cur[2];
            for (int[] d : dirs) {
                int ni = i + d[0], nj = j + d[1];
                if (ni >= 0 && ni < m && nj >= 0 && nj < n && !visited[ni][nj]) {
                    visited[ni][nj] = true;
                    water += Math.max(0, height - heightMap[ni][nj]);                  // trapped water = wall height minus this cell's own height
                    heap.offer(new int[]{Math.max(height, heightMap[ni][nj]), ni, nj});  // push back with the EFFECTIVE (raised) wall height
                }
            }
        }
        return water;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[][] heightMap = {{1, 4, 3, 1, 3, 2}, {3, 2, 1, 3, 2, 4}, {2, 3, 3, 2, 3, 1}};
