        for (auto& d : dirs) {
            int ni = i + d[0], nj = j + d[1];
            if (ni >= 0 && ni < m && nj >= 0 && nj < n && !visited[ni][nj]) {
                visited[ni][nj] = true;
                water += max(0, height - heightMap[ni][nj]);                          // trapped water = wall height minus this cell's own height
